% LECTURING-PART: P1
\textbf{Phần I: Trắc nghiệm nhiều lựa chọn} \textit{Thí sinh trả lời từ câu 1 đến câu 12. Mỗi câu hỏi thí sinh chỉ chọn một phương án.}

% LECTURING-SLOT: P1.1 ; topic=Ứng dụng đạo hàm: xét tính đơn điệu và cực trị ; level=NB
\noindent \textbf{Câu 1:} Cho hàm số $y=f(x)$ xác định và liên tục trên $\mathbb{R}$, có đạo hàm $f'(x)$ với bảng xét dấu sau:\\
% LECTURING-MATRIX: topic=Ứng dụng đạo hàm: xét tính đơn điệu và cực trị; level=NB
\begin{center}
\begin{adjustbox}{max width=\linewidth}
\begin{tabular}{|c|c|c|c|c|c|}
\hline
Khoảng hoặc điểm & $(-\infty;-1)$ & $-1$ & $(-1;2)$ & $2$ & $(2;+\infty)$ \\
\hline
$f'(x)$ & $-$ & $0$ & $+$ & $0$ & $-$ \\
\hline
\end{tabular}
\end{adjustbox}
\end{center}
Khẳng định nào sau đây đúng?\\
\noindent A. Hàm số đồng biến trên khoảng $(-1;2)$.\\
\noindent B. Hàm số nghịch biến trên khoảng $(-1;2)$.\\
\noindent C. Hàm số đạt cực tiểu tại $x=2$.\\
\noindent D. Hàm số đạt cực đại tại $x=-1$.
\par
% LECTURING-SLOT: P1.2 ; topic=Ứng dụng đạo hàm: đường tiệm cận của đồ thị hàm phân thức ; level=TH
\noindent \textbf{Câu 2:} Nồng độ của một loại thuốc trong máu (đơn vị mg/L) sau $t$ giờ kể từ lúc tiêm được cho bởi hàm số $C(t)=\dfrac{12t}{t+3}$ với $t\ge 0$. Khi thời gian $t$ kéo dài, nồng độ thuốc trong máu tiến dần về giá trị nào?\\
% LECTURING-MATRIX: topic=Ứng dụng đạo hàm: đường tiệm cận của đồ thị hàm phân thức; level=TH\\
\noindent A. Đường tiệm cận ngang $y=3$; nồng độ tiến dần về $3$ mg/L.\\
\noindent B. Đường tiệm cận ngang $y=0$; nồng độ tiến dần về $0$ mg/L.\\
\noindent C. Đường tiệm cận ngang $y=12$; nồng độ tiến dần về $12$ mg/L.\\
\noindent D. Đường tiệm cận ngang $y=4$; nồng độ tiến dần về $4$ mg/L.
\par
% LECTURING-SLOT: P1.3 ; topic=Ứng dụng tích phân: diện tích hình phẳng giới hạn bởi hai đường ; level=NB
\noindent \textbf{Câu 3:} Cho hình phẳng $(H)$ giới hạn bởi đồ thị hai hàm số $f(x)=4-x^2$ và $g(x)=x+2$ (phần tô màu trong hình vẽ). Diện tích $S$ của hình phẳng $(H)$ được tính bởi công thức nào sau đây?\\
% LECTURING-MATRIX: topic=Ứng dụng tích phân: diện tích hình phẳng giới hạn bởi hai đường; level=NB
\begin{center}
\begin{adjustbox}{max width=0.95\linewidth, max totalheight=0.38\textheight}
\begin{tikzpicture}[x=1.4cm, y=1cm, thick]
  % 1. Shaded region (drawn first)
  \fill[blue!15] plot[domain=-2:1, samples=60, variable=\x] ({\x}, {4-\x*\x}) -- (1,3) -- (-2,0) -- cycle;

  % 2. Axes
  \draw[->, thick] (-3,0) -- (3.3,0);
  \draw[->, thick] (0,-1.1) -- (0,5.3);

  % 3. Curves
  \draw[thick, blue!70!black, domain=-2.2:2.2, samples=80, variable=\x] plot ({\x}, {4-\x*\x});
  \draw[thick, red!70!black] (-2.6,-0.6) -- (2.4,4.4);

  % 4. Key points
  \fill (0,4) circle (1.5pt);
  \fill (0,2) circle (1.5pt);
  \fill (-2,0) circle (1.5pt);
  \fill (1,3) circle (1.5pt);

  % 5. Labels (drawn last)
    % captions last so nothing paints over them
    \node[below right=1pt] at (3.3,0) {$x$};
\node[right] at (0,5.3) {$y$};
\node[below left=2pt] at (0,0) {$O$};
\node[above left=3pt] at (0,4) {$4$};
\node[left] at (0,2) {$2$};
\node[below right=1pt] at (-2,0) {$(-2;0)$};
\node[anchor=west] at (1.3,2.8) {$(1;3)$};
\node[anchor=west] at (-2.3,3.4) {$y=4-x^2$};
\node[above left=2pt] at (2.4,4.4) {$y=x+2$};
\node[fill=white, inner sep=1.5pt] at (-0.4,2.4) {$S$};
\end{tikzpicture}
\end{adjustbox}
\end{center}
\noindent A. $\displaystyle S=\int_{-2}^{1}\left[(4-x^2)-(x+2)\right]dx$\\
\noindent B. $\displaystyle S=\int_{-1}^{2}\left[(4-x^2)-(x+2)\right]dx$\\
\noindent C. $\displaystyle S=\int_{-2}^{1}\left[(x+2)-(4-x^2)\right]dx$\\
\noindent D. $\displaystyle S=\int_{-2}^{1}\left[(4-x^2)+(x+2)\right]dx$
\par
% LECTURING-SLOT: P1.4 ; topic=Ứng dụng tích phân: thể tích vật thể có thiết diện thay đổi ; level=TH
\noindent \textbf{Câu 4:} Một vật thể nằm giữa hai mặt phẳng vuông góc với trục $Ox$ tại $x=0$ và $x=4$. Khi cắt vật thể bởi mặt phẳng vuông góc với $Ox$ tại điểm có hoành độ $x$ $(0\le x\le 4)$, thiết diện là tam giác đều có cạnh bằng $\sqrt{x}$. Thể tích của vật thể bằng\\
% LECTURING-MATRIX: topic=Ứng dụng tích phân: thể tích vật thể có thiết diện thay đổi; level=TH\\
\noindent\makebox[0.48\textwidth][l]{A. $8\sqrt{3}$}\makebox[0.48\textwidth][l]{B. $\dfrac{4\sqrt{3}}{3}$}\\
\noindent\makebox[0.48\textwidth][l]{C. $4\sqrt{3}$}\makebox[0.48\textwidth][l]{D. $2\sqrt{3}$}
\par
% LECTURING-SLOT: P1.5 ; topic=Hình học không gian: góc giữa đường thẳng và mặt phẳng ; level=NB
\noindent \textbf{Câu 5:} Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình vuông và cạnh bên $SA$ vuông góc với mặt phẳng $(ABCD)$ (hình vẽ). Góc giữa đường thẳng $SC$ và mặt phẳng $(ABCD)$ là góc nào sau đây?\\
% LECTURING-MATRIX: topic=Hình học không gian: góc giữa đường thẳng và mặt phẳng; level=NB
\begin{center}
\begin{adjustbox}{max width=0.95\linewidth, max totalheight=0.38\textheight}
\begin{tikzpicture}[scale=1.0, thick]
  % Toạ độ các đỉnh
  \coordinate (A) at (0,0);
  \coordinate (B) at (4,0);
  \coordinate (C) at (5.5,1.8);
  \coordinate (D) at (1.5,1.8);
  \coordinate (S) at (0,4.2);

  % Đường chéo đáy AC bị che: nét đứt
  \draw[dashed] (A) -- (C);

  % Các cạnh đáy và đường cao SA: nét liền
  \draw (A) -- (B) -- (C) -- (D) -- cycle;
  \draw (S) -- (A);

  % Các cạnh bên nhìn thấy: nét liền
  \draw (S) -- (B);
  \draw (S) -- (C);
  \draw (S) -- (D);

  % Chấm các đỉnh (không khoanh tròn nhãn)
  \fill (S) circle (1.5pt);
  \fill (A) circle (1.5pt);
  \fill (B) circle (1.5pt);
  \fill (C) circle (1.5pt);
  \fill (D) circle (1.5pt);

  % Nhãn đặt ngoài hình, vẽ sau cùng
  \node[above=3pt] at (S) {$S$};
  \node[below left=2pt] at (A) {$A$};
  \node[below right=2pt] at (B) {$B$};
  \node[above right=2pt] at (C) {$C$};
  \node[left=4pt] at (D) {$D$};
\end{tikzpicture}
\end{adjustbox}
\end{center}
\noindent\makebox[0.24\textwidth][l]{A. $\widehat{SCD}$}\makebox[0.24\textwidth][l]{B. $\widehat{SAC}$}\makebox[0.24\textwidth][l]{C. $\widehat{SCB}$}\makebox[0.24\textwidth][l]{D. $\widehat{SCA}$}
\par
% LECTURING-SLOT: P1.6 ; topic=Hình học không gian: thể tích khối chóp và khối lăng trụ ; level=TH
\noindent \textbf{Câu 6:} Một khối chóp và một khối lăng trụ có cùng diện tích đáy và cùng chiều cao. Nếu tăng chiều cao của khối chóp lên gấp đôi (vẫn giữ diện tích đáy) và giữ nguyên khối lăng trụ, thì tỉ số $\dfrac{V_{\text{chóp}}}{V_{\text{lăng trụ}}}$ mới bằng\\
% LECTURING-MATRIX: topic=Hình học không gian: thể tích khối chóp và khối lăng trụ; level=TH\\
\noindent\makebox[0.24\textwidth][l]{A. $\dfrac{1}{2}$}\makebox[0.24\textwidth][l]{B. $\dfrac{1}{3}$}\makebox[0.24\textwidth][l]{C. $\dfrac{2}{3}$}\makebox[0.24\textwidth][l]{D. $\dfrac{3}{2}$}
\par
% LECTURING-SLOT: P1.7 ; topic=Vectơ và tọa độ trong không gian Oxyz ; level=NB
\noindent \textbf{Câu 7:} Trong không gian $Oxyz$, cho $\overrightarrow{u}=(2;-1;3)$ và $\overrightarrow{v}=(1;4;-2)$. Tọa độ của vectơ $\overrightarrow{u}+\overrightarrow{v}$ là\\
% LECTURING-MATRIX: topic=Vectơ và tọa độ trong không gian Oxyz; level=NB\\
\noindent\makebox[0.24\textwidth][l]{A. $(3;3;1)$}\makebox[0.24\textwidth][l]{B. $(1;-5;5)$}\makebox[0.24\textwidth][l]{C. $(3;-5;1)$}\makebox[0.24\textwidth][l]{D. $(3;3;5)$}
\par
% LECTURING-SLOT: P1.8 ; topic=Phương pháp tọa độ: vectơ pháp tuyến và vectơ chỉ phương ; level=NB
\noindent \textbf{Câu 8:} Trong không gian $Oxyz$, mặt phẳng $(P)$ có phương trình $2x-3y+z-5=0$. Vectơ nào sau đây là một vectơ pháp tuyến của $(P)$?\\
% LECTURING-MATRIX: topic=Phương pháp tọa độ: vectơ pháp tuyến và vectơ chỉ phương; level=NB\\
\noindent\makebox[0.48\textwidth][l]{A. $\overrightarrow{n}=(2;-3;1)$}\makebox[0.48\textwidth][l]{B. $\overrightarrow{n}=(2;-3;-5)$}\\
\noindent\makebox[0.48\textwidth][l]{C. $\overrightarrow{n}=(2;3;1)$}\makebox[0.48\textwidth][l]{D. $\overrightarrow{n}=(1;-3;2)$}
\par
% LECTURING-SLOT: P1.9 ; topic=Mũ và lôgarit: tính chất của lũy thừa và lôgarit ; level=NB
\noindent \textbf{Câu 9:} Với $a>0$, $a\neq 1$ và $x,y>0$, mệnh đề nào sau đây đúng?\\
% LECTURING-MATRIX: topic=Mũ và lôgarit: tính chất của lũy thừa và lôgarit; level=NB\\
\noindent A. $\log_a\dfrac{x}{y}=\dfrac{\log_a x}{\log_a y}$\\
\noindent B. $\log_a(x+y)=\log_a x+\log_a y$\\
\noindent C. $\log_a(x^2)=2\log_a x$\\
\noindent D. $\log_a(xy)=\log_a x\cdot\log_a y$
\par
% LECTURING-SLOT: P1.10 ; topic=Dãy số, cấp số cộng và cấp số nhân: số hạng tổng quát ; level=NB
\noindent \textbf{Câu 10:} Số lượng vi khuẩn trong một mẫu nuôi cấy tăng gấp đôi sau mỗi giờ. Gọi $u_n$ là số lượng vi khuẩn sau $n$ giờ $(n\ge 1)$, với $u_1=500$. Dãy số $(u_n)$ là một cấp số nhân. Số hạng tổng quát $u_n$ của dãy là\\
% LECTURING-MATRIX: topic=Dãy số, cấp số cộng và cấp số nhân: số hạng tổng quát; level=NB\\
\noindent\makebox[0.48\textwidth][l]{A. $u_n=500+2(n-1)$}\makebox[0.48\textwidth][l]{B. $u_n=500\cdot 2^{\,n-1}$}\\
\noindent\makebox[0.48\textwidth][l]{C. $u_n=2\cdot 500^{\,n-1}$}\makebox[0.48\textwidth][l]{D. $u_n=500\cdot 2^{\,n}$}
\par
% LECTURING-SLOT: P1.11 ; topic=Số đặc trưng xu thế trung tâm của mẫu số liệu ghép nhóm ; level=NB
\noindent \textbf{Câu 11:} Thời gian chờ khám bệnh (đơn vị: phút) của $39$ bệnh nhân tại một phòng khám được ghi trong bảng tần số ghép nhóm sau:\\
% LECTURING-MATRIX: topic=Số đặc trưng xu thế trung tâm của mẫu số liệu ghép nhóm; level=NB
\begin{center}
\begin{adjustbox}{max width=\linewidth}
\begin{tabular}{|c|c|c|c|c|c|}
\hline
Thời gian (phút) & $[0;5)$ & $[5;10)$ & $[10;15)$ & $[15;20)$ & $[20;25)$ \\
\hline
Số bệnh nhân & $5$ & $10$ & $8$ & $12$ & $4$ \\
\hline
\end{tabular}
\end{adjustbox}
\end{center}
Nhóm chứa trung vị của mẫu số liệu ghép nhóm trên là\\
\noindent\makebox[0.24\textwidth][l]{A. $[15;20)$}\makebox[0.24\textwidth][l]{B. $[20;25)$}\makebox[0.24\textwidth][l]{C. $[5;10)$}\makebox[0.24\textwidth][l]{D. $[10;15)$}
\par
% LECTURING-SLOT: P1.12 ; topic=Xác suất có điều kiện: công thức và bảng hai chiều ; level=TH
\noindent \textbf{Câu 12:} Thống kê số học sinh của một trường THPT theo khối lớp và hình thức học được cho trong bảng sau:\\
% LECTURING-MATRIX: topic=Xác suất có điều kiện: công thức và bảng hai chiều; level=TH
\begin{center}
\begin{adjustbox}{max width=\linewidth}
\begin{tabular}{|c|c|c|c|}
\hline
Khối lớp & Trực tuyến & Trực tiếp & Tổng \\
\hline
Khối 10 & $12$ & $13$ & $25$ \\
\hline
Khối 11 & $25$ & $20$ & $45$ \\
\hline
Khối 12 & $18$ & $32$ & $50$ \\
\hline
Tổng & $55$ & $65$ & $120$ \\
\hline
\end{tabular}
\end{adjustbox}
\end{center}
Chọn ngẫu nhiên một học sinh của trường. Biết học sinh được chọn thuộc khối 12, xác suất để em đó học trực tuyến bằng\\
\noindent\makebox[0.24\textwidth][l]{A. $\dfrac{2}{5}$}\makebox[0.24\textwidth][l]{B. $\dfrac{3}{20}$}\makebox[0.24\textwidth][l]{C. $\dfrac{5}{12}$}\makebox[0.24\textwidth][l]{D. $\dfrac{9}{25}$}

\vspace{0.5cm}
% LECTURING-PART: P2
\textbf{Phần II: Trắc nghiệm đúng/sai} \textit{Thí sinh trả lời từ câu 1 đến câu 4. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.}

\noindent\textbf{Câu 1.} Xét tính đúng, sai của mỗi mệnh đề sau.\par
a) Nếu $f'(x) > 0$ với mọi $x \in (a; b)$ thì hàm số $y = f(x)$ đồng biến trên khoảng $(a; b)$.\par
b) Hàm số $y = x^3 - 3x^2 - 9x + 5$ đạt cực tiểu tại $x = -1$ và giá trị cực tiểu của hàm số bằng $10$.\par
c) Hàm số $y = x^3 - 3x^2 + 3mx + 1$, với $m$ là tham số, có hai điểm cực trị có hoành độ trái dấu khi và chỉ khi $m < 0$.\par
d) Cho hàm số $y = f(x)$ xác định và liên tục trên $\mathbb{R}$, có đồ thị của hàm số $y = f'(x)$ như hình vẽ. Hàm số $f$ đạt cực đại tại $x = -1$ và $f(3) > f(-1)$.\par
\begin{center}
\begin{adjustbox}{max width=0.95\linewidth, max totalheight=0.38\textheight}
